package com.sakti.banking.controller; import com.sakti.banking.dto.*; import com.sakti.banking.service.AccountService; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/accounts") public class AccountController {private final AccountService accounts;public AccountController(AccountService a){accounts=a;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public AccountResponse create(Authentication a,@Valid @RequestBody CreateAccountRequest r){return accounts.create(a.getName(),r);} @GetMapping public List<AccountResponse> mine(Authentication a){return accounts.myAccounts(a.getName());} @GetMapping("/dashboard") public DashboardResponse dashboard(Authentication a){return accounts.dashboard(a.getName());} @PostMapping("/{n}/deposit") public AccountResponse deposit(Authentication a,@PathVariable String n,@Valid @RequestBody MoneyRequest r){return accounts.deposit(a.getName(),n,r);} @PostMapping("/{n}/withdraw") public AccountResponse withdraw(Authentication a,@PathVariable String n,@Valid @RequestBody MoneyRequest r){return accounts.withdraw(a.getName(),n,r);} @PostMapping("/transfer") public Map<String,String> transfer(Authentication a,@Valid @RequestBody TransferRequest r){accounts.transfer(a.getName(),r);return Map.of("status","SUCCESS","message","Transfer completed");} @GetMapping("/{n}/transactions") public List<TransactionResponse> tx(Authentication a,@PathVariable String n){return accounts.transactions(a.getName(),n);} @PostMapping("/{n}/closure-request") public AccountResponse close(Authentication a,@PathVariable String n){return accounts.requestClosure(a.getName(),n);} }
